tests.pseudocode:
for sc in gen(seed, n=30):
  for runner in [RunArgv, Run]:
    res, err = runner(sc.ctx(), sc.cmd, sc.opts)
    assert err == nil
    assert res.Outcome in {ok, exit, signal, timeout, abort}
    assert res.Outcome == sc.expected and res.ExitCode == sc.expectedCode

for call in [RunArgv(ctx, nil, {}), RunArgv(ctx, ['agentkit-no-such-program-04'], {}), RunArgv(ctx, ['true'], {Dir: tmp+'/missing'}), RunArgv(ctx, ['true'], {LogPath: tmp+'/blocker/run.log'})]:
  res, err = call; assert reflect.DeepEqual(res, ExecResult{}) and err != nil
for (call, want) in started: res, err = call; assert err == nil and res.Outcome == want

for res in bases:
  a = execResultToTool(res, 30s); res.IOErr = errors.New('log write failed: disk full'); b = execResultToTool(res, 30s)
  assert a.Text == b.Text and deepEqual(a.Data, b.Data) and a.Error == b.Error and deepEqual(*a.Metadata, *b.Metadata)
  assert 'disk full' not in b.Text and keys(b.Data) == {'output','exit_code','outcome'}

for (n, k) in gen(seed):
  res = runWith(reusingTool, turns(n, batch=k))
  for md in retained: md.Outcome = 'mutated'; *md.ExitCode = 999
  for msg in toolResults(res.Messages) + toolResults(agent.History()) + capturedEvents:
    assert *msg.Metadata.ExitCode == msg.callIndex and msg.Metadata.Outcome == 'call-'+msg.callIndex

agent.Run(ctx, 'go'); store.Close()
for md in [evt.Message.Metadata, decodedEntry(reopen(path)).Metadata, stopCtx.ToolResults[0].Metadata, toolResult(agent.History()).Metadata]:
  assert md.Outcome == 'edited' and *md.ExitCode == 99

runWith(probe, after=func(in){ snap = in.Result.Clone(); in.ToolResult.Text='y'; in.ToolResult.Data['k']=2; in.ToolResult.Metadata.Outcome='hacked'; *in.ToolResult.Metadata.ExitCode=7 })
for m in [evt.Message, toolResult(agent.History()), stopCtx.ToolResults[0]]:
  assert deepEqual(m.Content, snap.Content) and m.IsError == snap.IsError and deepEqual(*m.Metadata, *snap.Metadata)

for m in gen(seed, n=1000):
  b = session.EncodeMessage(m); d = session.DecodeMessage(b)
  assert (d.Metadata == nil) == (m.Metadata == nil)
  if m.Metadata != nil: assert deepEqual(*d.Metadata, *m.Metadata)
  assert session.EncodeMessage(d) == b
